// Presentation-only helpers. Calculation stays in policy.js / engine.js.
export function policyInputHTML(state,{field,select,check,years,escape}){const p=state.opi2Policy;return `<section class="policy-inputs"><div class="panel-head"><div><h3>15시 공개 내용 · 특별경영성과급 입력</h3><p class="subtitle">전년도 성과에 따라 지급되는 업무성과급은 독립 금액으로 직접 입력합니다. OPI1·TAI로 자동 대체하지 않습니다. CL1 조건은 확인 대기입니다.</p></div><span class="pill difference">모델 확인 대기</span></div><div class="grid three">${select('계산 경로','opi2Policy.mode',p.mode,[['review','새 지급안 · 주식·정산 연결 추정'],['estimate','이전 순세후 모형 · 참고용']])}${select('지급률 산정 방식','opi2Policy.rateSource',p.rateSource,[['legacy','영업이익 전망으로 개인 예상 지급률 산출'],['direct','특별성과급 지급률 직접 입력']])}${select('기부금 · 총 지급액 세전 기준','opi2Policy.donationRate',p.donationRate,[.002,.004,.006,.008,.01].map(v=>[v,(v*100).toFixed(1)+'%']))}${select('직접 지급률의 적용 범위','opi2Policy.rateScope',p.rateScope,[['memory','메모리 기준률 · 소속계수 별도'],['personal','개인소속률 · 소속계수 이미 포함']])}</div><div class="grid three" style="margin-top:14px">${select('소득신고 주수 정의 · 회사 확인 전 가정','opi2Policy.reportedSharesDefinition',p.reportedSharesDefinition,[['gross_equivalent','공제전 환산주수 · 합리적 추론 기본값'],['net_delivered','공제후 환산주수 · 비교 가정']])}${select('49.5% 선제 세금 기준 · 미확정 가정','opi2Policy.taxWithholdingBase',p.taxWithholdingBase,[['employment_income','종가 근로소득 Y · 추정 가정'],['gross','세전 지급액 G · 비교 가정']])}${select('4.967% 보험 기준 · 미확정 가정','opi2Policy.insuranceWithholdingBase',p.insuranceWithholdingBase,[['gross','세전 지급액 G · 추정 가정'],['employment_income','종가 근로소득 Y · 비교 가정']])}</div><p class="disclosure">공제전 환산주수 = G ÷ 세 VWAP 평균 R, 근로소득 예시 Y = 공제전 환산주수 × 지급일 종가 C. 근로소득 반영이라는 설명에 따른 합리적 추론을 기본값으로 사용하되 회사의 실제 주식수 정의가 확인된 것은 아닙니다. 세금·보험료 공제 기준은 별도 선택한 추정 가정입니다.</p><div class="inline" style="margin:14px 0">${check('2027 이후도 같은 규칙 가정 (회사 확정 아님)','opi2Policy.repeatFutureYears',p.repeatFutureYears)}</div><div class="notice">공통 기본값은 메모리 기준 특별성과급 전체의 70%입니다. 개인소속 지급률을 입력하면 그 지급률에 소속계수가 이미 포함되므로 다시 곱하지 않습니다. 파운드리·시스템LSI0.30은 기존 단순비례 가정이며 최종 사업부 지급률이 아닙니다. 고급 설정의 계수 또는 개인소속 직접 지급률로 수정할 수 있습니다. 영업이익 전망률은 개인소속 계수를 이미 포함한 예상률입니다. 이 예상률에 계약연봉+업무성과급과 CL4 배수·학술연수 계수를 적용합니다. 직접률 방식에서는 지급률 범위를 선택하세요. 주가25만원, 4월1일 지급예정, 업무성과급0원은 변경 가능한 예시 가정입니다.</div><div class="table-wrap"><table class="year-form"><thead><tr><th>성과연도</th><th>당해 CL</th><th>CL4 업적고과</th><th>업무성과급 (원)</th><th>직접 지급률 (%)<div class="tiny">직접입력 모드 전용</div></th><th>예상 지급연도</th><th>지급일 · 확정/가정</th><th>세금 정산연도</th><th>보험 정산연도</th></tr></thead><tbody>${years(state).map(y=>`<tr><td>${y}${y!==2026?'<div class="reason">미래 반복 조건 미확정</div>':''}</td><td>${select(y+' 당해 CL',`opi2Policy.gradeByYear.${y}`,p.gradeByYear[y]??'',[['','직급 선택'],['CL1','CL1 · 조건 미확인'],['CL2','CL2'],['CL3','CL3'],['CL4','CL4']])}</td><td>${select(y+' CL4 고과',`opi2Policy.ratingByYear.${y}`,p.ratingByYear[y]??'',[['','고과 선택'],['EM','EM ×1.4'],['ES','ES ×1.2'],['MT','MT ×1'],['MS','MS ×0.9'],['NM','NM ×0.8']])}</td><td>${field(y+' 업무성과급 원',`opi2Policy.workBonusByYear.${y}`,p.workBonusByYear[y],{unit:'원',step:1,placeholder:'전년도 성과 기준 · 직접 입력'})}</td><td>${field(y+' 특별성과급 지급률',`opi2Policy.paymentRateByYear.${y}`,p.paymentRateByYear[y],{unit:'%',scale:.01,max:10000,placeholder:'확인 지급률 직접 입력'})}</td><td>${field(y+' 예상 지급연도',`opi2Policy.expectedPaymentYearByYear.${y}`,p.expectedPaymentYearByYear[y],{step:1,min:y,max:2065,placeholder:y===2026?'2027':'미확정'})}</td><td>${field(y+' 지급일 입력',`opi2Policy.paymentDateByYear.${y}`,p.paymentDateByYear[y],{type:'date',hint:'미확정 날짜는 가정으로만 표시'})}${check(y+' 실제 지급일 확정',`opi2Policy.paymentDateConfirmedByYear.${y}`,p.paymentDateConfirmedByYear[y])}</td><td>${field(y+' 세금 현금 정산연도',`opi2Policy.taxSettlementYearByOrigin.${y}`,p.taxSettlementYearByOrigin[y],{step:1,min:y,max:2065,placeholder:String(Number((p.paymentDateByYear[y]??'').slice(0,4)||p.expectedPaymentYearByYear[y]||y+1)+p.taxSettlementDelay)})}</td><td>${field(y+' 보험 현금 정산연도',`opi2Policy.insuranceSettlementYearByOrigin.${y}`,p.insuranceSettlementYearByOrigin[y],{step:1,min:y,max:2065,placeholder:String(Number((p.paymentDateByYear[y]??'').slice(0,4)||p.expectedPaymentYearByYear[y]||y+1)+p.insuranceSettlementDelay)})}</td></tr>`).join('')}</tbody></table></div><p class="disclosure">2026 기초금액은 2026 계약연봉 + 전년도 성과에 따라 지급되는 업무성과급 직접 입력액입니다. 이 금액은 특별성과급 기초금액 전용 입력이며 별도 현금 지급항목으로 이중 합산하지 않습니다. 미래 연도 반복은 사용자가 선택한 가정이며 회사 확정 조건이 아닙니다. CL4에만 업적고과 배수를 적용합니다. 학술연수 계수는 기존 사용자 가정을 참고한 미확정 결합 조건입니다.</p><details open><summary>지급일 기준 주가 · 종가 분리</summary><div class="table-wrap"><table class="year-form"><thead><tr><th>성과연도</th><th>지급 전 1주 VWAP (원)</th><th>지급 전 1개월 VWAP (원)</th><th>지급 전 2개월 VWAP (원)</th><th>지급일 종가 (원)</th></tr></thead><tbody>${years(state).map(y=>`<tr><td>${y}</td><td>${field(y+' 1주 VWAP',`opi2Policy.vwapWeekByYear.${y}`,p.vwapWeekByYear[y],{step:1,min:1})}</td><td>${field(y+' 1개월 VWAP',`opi2Policy.vwapMonthByYear.${y}`,p.vwapMonthByYear[y],{step:1,min:1})}</td><td>${field(y+' 2개월 VWAP',`opi2Policy.vwapTwoMonthsByYear.${y}`,p.vwapTwoMonthsByYear[y],{step:1,min:1})}</td><td>${field(y+' 지급일 종가',`opi2Policy.closingPriceByYear.${y}`,p.closingPriceByYear[y],{step:1,min:1})}</td></tr>`).join('')}</tbody></table></div><p class="disclosure">기준주가는 세 VWAP의 산술평균입니다. 지급일 종가와 구분합니다. VWAP는 계산용 원 정수 입력이며 평균은 정확한 분수로 보존합니다. 실제 주식 수량 반올림·단주 처리는 확인 대기입니다.</p></details><details><summary>선제징수 · 현금 정산 가정</summary><div class="grid two">${field('세금 정산 기본 지연','opi2Policy.taxSettlementDelay',p.taxSettlementDelay,{unit:'년',step:1,max:10})}${field('보험 정산 기본 지연','opi2Policy.insuranceSettlementDelay',p.insuranceSettlementDelay,{unit:'년',step:1,max:10})}</div><p class="disclosure">기본 과세/지급연도 다음해 현금 정산 가정이며 회차별 정산연도를 지정할 수 있습니다. 실제 연말정산 공제·보험료 결정/정산 시차는 미반영입니다. 환급은 현금이며 주식수를 늘리지 않습니다. PSU에는 새 선징수율을 적용하지 않습니다.</p><div class="grid two">${field('지급전 세금 선제징수율','opi2Policy.withholdingTaxRate',p.withholdingTaxRate,{unit:'%',scale:.01,max:100})}${field('지급전 보험료 선제징수율','opi2Policy.withholdingInsuranceRate',p.withholdingInsuranceRate,{unit:'%',scale:.01,max:100})}</div><p class="disclosure">기본 세금49.5% = 소득세45% + 지방세4.5%. 보험료4.967% = 건강3.595% + 장기요양0.472% + 고용0.9%. 이 선징수에 국민연금은 포함하지 않습니다. 기존 최종 연간 세후 모형과 독립이며 합계에서 중복 차감하지 않습니다.</p><p class="disclosure">업무성과급 정의: ${escape('전년도 성과 기준 · 독립 금액 직접 입력 확인')}. 소득신고 주식수 정의: ${escape(p.reportedSharesDefinition==='gross_equivalent'?'공제전 환산주수 · 추론 기본가정 · 회사 확인 전':'공제후 환산주수 · 비교 가정 · 회사 확인 전')}. 지급전 공제·최종 세금·환급/추가징수·기부금 세액공제는 서로 구분합니다.</p></details></section>`;}
export function policyReviewHTML(ledger,{amount,escape,warning}){const value=n=>n===null||n===undefined?'미확정':amount(n);return `<section class="panel"><div class="panel-head"><div><h2>공개안 지급·선제징수 검토 원장</h2><p class="subtitle">확정 총보상 또는 최종 연간 세후 현금흐름이 아닙니다.</p></div><span class="pill difference">정의 확인 대기</span></div><div class="notice">${escape(ledger.disclaimer)}</div><div class="table-wrap"><table><thead><tr><th>발생연도</th><th>기초금액 예시</th><th>세전 지급액 예시</th><th>선택 가정 선제 세금</th><th>선택 가정 선제 보험료</th><th>기부금 예시</th><th>선택 가정 주식예산</th><th>확인 상태</th></tr></thead><tbody>${ledger.rows.map(r=>`<tr><td>${r.originYear}</td><td>${value(r.basis)}</td><td>${value(r.preliminaryGross)}</td><td>${value(r.selectedWithholdingScenario?.tax)}</td><td>${value(r.selectedWithholdingScenario?.insurance)}</td><td>${value(r.selectedWithholdingScenario?.donation)}</td><td>${value(r.selectedWithholdingScenario?.stockBudget)}</td><td><span class="difference">가정 기반 · 회사 확인 전</span></td></tr>`).join('')}</tbody></table></div>${warning()}${ledger.rows.map(r=>`<details><summary>${r.originYear} 발생분 · 지급·평가·매각제한 상세</summary><p class="disclosure">선택 공제 가정: ${escape(r.selectedWithholdingScenario?.name??'필요 입력 대기')}. 실제 입고주수·최종 세금·정산 현금흐름은 별도 확인합니다.</p><p class="disclosure">${escape(r.reasons.join(' · ')||'최종 세무/주식수 모델 확인 대기')}</p><div class="grid three"><div class="mini-card"><div class="muted">기준주가 · 세 VWAP 산술평균</div><div class="big">${r.prices.mean?(r.prices.mean.numerator/r.prices.mean.denominator).toLocaleString('ko-KR',{maximumFractionDigits:6})+'원':'미입력'}</div><div class="tiny">${r.prices.mean?'정확값 '+r.prices.mean.numerator+'/3 원':'종가로 대체하지 않음'}</div></div><div class="mini-card"><div class="muted">지급일 종가</div><div class="big">${r.prices.closingPrice===null?'미입력':r.prices.closingPrice.toLocaleString()+'원'}</div><div class="tiny">근로소득 평가 가격 · 기준주가와 별개</div></div><div class="mini-card"><div class="muted">실제 지급일</div><div class="big">${r.payment.actualDate??(r.payment.assumedDate?r.payment.assumedDate+' (가정)':'미확정')}</div><div class="tiny">${r.payment.expectedYear??'연도 미확정'} · ${r.payment.expectedWindow}</div></div></div><div class="table-wrap"><table><thead><tr><th>회차</th><th>실제 지급일 기준 매각가능일</th><th>미확정 일정 참고연도</th><th>주식예산 평가액 예시</th></tr></thead><tbody>${r.releases.map(t=>`<tr><td>${t.tranche}/3</td><td>${t.availableDate??(t.assumedAvailableDate?t.assumedAvailableDate+' (가정 · 미확정)':'실제 지급일 확인 대기')}</td><td>${t.expectedYear??'미확정'} ${t.confirmedDate?'':'(예상 · 현금흐름 미반영)'}</td><td>${value(t.amount)}</td></tr>`).join('')}</tbody></table></div><p class="disclosure">즉시/1년/2년 제한은 실제 지급일부터 기산합니다. 각 금액은 주식예산을 1원까지 보존하여 나눈 평가 예시이며 실제 입고주수·매각현금은 미확정입니다.</p><div class="grid two"><div class="mini-card"><div class="muted">공제 전 환산주수 정의를 가정한 종가 평가</div><div class="big">${value(r.shareIncomeCandidates?.grossEquivalent)}</div><div class="tiny">정의 비교용 예시 · 확정 근로소득 아님</div></div><div class="mini-card"><div class="muted">공제 후 환산주수 정의를 가정한 종가 평가</div><div class="big">${value(r.shareIncomeCandidates?.netDeliveredEquivalent)}</div><div class="tiny">정의 비교용 예시 · 확정 근로소득 아님</div></div></div><h3 style="margin-top:16px">서로 다른 정의의 선제징수 가상 시나리오</h3><p class="disclosure">아래 세 가지 모두 수학적 원 보존이 가능합니다. 따라서 합계 검증만으로 회사의 정책 정답을 고를 수 없습니다. 주식수 신고 정의와 보험료 기준이 확인될 때까지 어느 사례도 확정 지급액으로 선택하지 않습니다. 종가가 기준가보다 높으면 공제 전 주수 신고 사례의 선징수액이 주식예산을 초과할 수도 있습니다.</p><div class="table-wrap"><table><thead><tr><th>정의 가정</th><th>종가 평가 근로소득 예시</th><th>선제 세금 예시</th><th>선제 보험 예시</th><th>공제 후 주식예산 예시</th><th>소수 환산 입고주수 예시</th></tr></thead><tbody>${r.withholdingAlternatives.map(c=>`<tr><td>${escape(c.name)}</td><td>${value(c.reportedEmploymentIncomeExample)}</td><td>${value(c.tax)}</td><td>${value(c.insurance)}</td><td>${value(c.stockBudget)}${c.unfundedDeduction?' (공제 재원 부족)':''}</td><td>${c.netFractionalShares===null?'확인 필요':c.netFractionalShares.toLocaleString('ko-KR',{maximumFractionDigits:8})+'주'} (미확정 예시)</td></tr>`).join('')}</tbody></table></div><p class="disclosure">공제전 소수 환산주수: ${r.shares.fractionalGrossShares?.toLocaleString('ko-KR',{maximumFractionDigits:8})??'미확정'} · 공제후 소수 환산주수: ${r.shares.fractionalNetShares?.toLocaleString('ko-KR',{maximumFractionDigits:8})??'미확정'}. 실제 총 지급주식수, 신고 근로소득, 최종 연간 세금/보험료, 환급/추가징수는 아직 확정하지 않았습니다.</p><pre class="log">${escape(JSON.stringify(r,null,2))}</pre>${warning()}</details>`).join('')}<div class="actions" style="margin-top:14px"><button data-action="json">검토 원장 JSON 내보내기</button><button data-action="csv">검토 원장 CSV 내보내기</button><button data-action="copy">검토 요약 복사</button></div><div id="summary-box" class="summary-box"><label for="summary-text">검토 원장 요약 · 직접 복사</label><textarea id="summary-text" readonly></textarea></div><p class="disclosure">생활비·부동산 비용 차감 전이며 수수료·매각세금은0원 가정입니다. 미확정 환급/추가징수는 현금흐름에 넣지 않았습니다.</p></section>`;}
